(async()=>{try{if(!window.motionHistoryReady)await new Promise(r=>window.addEventListener('motion-history-ready',r,{once:true}));const api=await import('./mesh-walk.js?v=motion-v70'),controls=await import('./walk-controls.js?v=motion-v70');registerCapability('meshWalk',{label:'Natural mesh walk',category:'Character animation',defaults:structuredClone(api.meshWalkDefaults),slots:['walkAtlas',...Object.keys(api.meshWalkDefaults.walkPartRects).map(n=>'walkPart'+n[0].toUpperCase()+n.slice(1))],render(c,age,l){api.paintMeshWalk(c,age,sprites,[100,-20,760,580],l.params)},edit(host,l,save){controls.mountWalkControls(host,l.params,{images:sprites,save,replace:chooseAsset,refresh:renderBlankInspector})}});const button=document.createElement('button');button.className='pill';button.textContent='Walk studio';button.onclick=()=>{openBlank();addBlankLayer('meshWalk')};document.querySelector('#openEditor').parentElement.append(button);window.MotionWalkStudio={...api,...controls};}catch(e){console.error('Walk studio:',e)}})();
